```js
// In-memory index implementation mirroring the subset of whoosh.index
// used by the original Python program.

export class Index {
  constructor(dirname, schema) {
    this.dirname = dirname;
    this.schema = schema;
    this._documents = [];
  }

  writer() {
    return new IndexWriter(this);
  }

  searcher() {
    return new IndexSearcher(this);
  }
}

export class IndexWriter {
  constructor(index) {
    this.index = index;
    this._pending = [];
  }

  addDocument(fields) {
    this._pending.push(fields);
  }

  commit() {
    this.index._documents.push(...this._pending);
    this._pending = [];
  }
}

export class IndexSearcher {
  constructor(index) {
    this.index = index;
  }

  search(query) {
    return this.index._documents.filter((doc) => query.matches(doc));
  }
}

export function createIn(dirname, schema) {
  return new Index(dirname, schema);
}
```

**`argparse.mjs`** — manual `process.argv` parsing replicating Python argparse byte-exactly (usage/help/error text, exit codes 0/2, `--opt val` and `--opt=val`, last-wins duplicates, required-check before unrecognized-check):
```js
// Minimal reimplementation of the subset of Python's argparse behavior
// used by this program: required long options, -h/--help, byte-exact
// usage/help/error output, and exit codes 0 (help) / 2 (errors).

import path from 'node:path';

export class ArgumentParser {
  constructor(options = {}) {
    this.prog = options.prog !== undefined
      ? options.prog
      : path.basename(process.argv[1]);
    // Added arguments, in order of addition: { name, dest, metavar, required }
    this.arguments = [];
  }

  addArgument(name, options = {}) {
    const { required = false } = options;
    const dest = name.replace(/^--/, '');
    this.arguments.push({
      name,
      dest,
      metavar: dest.toUpperCase(),
      required: Boolean(required),
    });
  }

  _usageLine() {
    let line = `usage: ${this.prog} [-h]`;
    for (const arg of this.arguments) {
      line += ` --${arg.dest} ${arg.metavar}`;
    }
    return line;
  }

  _helpText() {
    const lines = [this._usageLine(), '', 'options:'];
    lines.push('  -h, --help  show this help message and exit');
    for (const arg of this.arguments) {
      lines.push(`  --${arg.dest} ${arg.metavar}`);
    }
    return lines.join('\n') + '\n';
  }

  _printHelpAndExit() {
    process.stdout.write(this._helpText());
    process.exit(0);
  }

  _errorAndExit(message) {
    process.stderr.write(`${this._usageLine()}\n${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  parseArgs(argv = process.argv.slice(2)) {
    const byName = new Map(this.arguments.map((arg) => [arg.name, arg]));
    const values = {};
    const extras = [];

    let i = 0;
    while (i < argv.length) {
      const token = argv[i];

      if (token === '-h' || token === '--help') {
        this._printHelpAndExit();
      }

      if (token.startsWith('--') && token.includes('=')) {
        const eq = token.indexOf('=');
        const name = token.slice(0, eq);
        const value = token.slice(eq + 1);
        const arg = byName.get(name);
        if (arg) {
          values[arg.dest] = value;
        } else {
          extras.push(token);
        }
        i += 1;
        continue;
      }

      if (token.startsWith('--')) {
        const arg = byName.get(token);
        if (arg) {
          const next = argv[i + 1];
          if (next === undefined || (next.startsWith('-') && next !== '-')) {
            this._errorAndExit(`argument ${arg.name}: expected one argument`);
          }
          values[arg.dest] = next;
          i += 2;
          continue;
        }
        extras.push(token);
        i += 1;
        continue;
      }

      // Unknown short option or bare positional.
      extras.push(token);
      i += 1;
    }

    const missing = this.arguments
      .filter((arg) => arg.required && !(arg.dest in values))
      .map((arg) => arg.name);
    if (missing.length > 0) {
      this._errorAndExit(
        `the following arguments are required: ${missing.join(', ')}`,
      );
    }

    if (extras.length > 0) {
      this._errorAndExit(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return values;
  }
}
```

## Entry file (`/output/test11.mjs`)

```js
import { ArgumentParser } from './lib/argparse.mjs';
import { Schema, TEXT, ID } from './lib/fields.mjs';
import { createIn } from './lib/index.mjs';
import { QueryParser } from './lib/qparser.mjs';
import { Every } from './lib/query.mjs';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

const parser = new ArgumentParser();
parser.addArgument('--a', { required: true });
parser.addArgument('--b', { required: true });
parser.addArgument('--c', { required: true });
const args = parser.parseArgs();

const schema = new Schema({ title: new TEXT({ stored: true }), content: new TEXT() });
const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'test11-'));
const ix = createIn(tempDir, schema);
const writer = ix.writer();
writer.addDocument({ title: args.a, content: args.b });
writer.addDocument({ title: args.b, content: args.c });
writer.addDocument({ title: args.c, content: args.a });
writer.commit();
const searcher = ix.searcher();
const everyQuery = new Every();
const results = searcher.search(everyQuery);
console.log(results.length);
```

## Verification (run against the executable)

- `node test11.mjs --a hello --b world --c foo` → `3`, exit 0 — matches executable (also with `--a=x` form, empty strings, and unicode values).
- `--help` output is **byte-identical** to the executable's (modulo prog name `test11.mjs` vs `test11_executable`, which is correct argparse behavior — prog = script basename).
- Missing arg → `error: the following arguments are required: --c`, exit 2; `--a` without value → `argument --a: expected one argument`, exit 2; `--extra w` → `unrecognized arguments: --extra w`, exit 2; required-check precedence over unrecognized confirmed identical.
- ESM only, `.mjs` everywhere, full-suffix local imports, zero npm dependencies, only `node:` built-ins used.
